src = r'''
#include <cublasLt.h>
#include <cuda_runtime.h>
#include <string.h>
static cublasLtHandle_t h=nullptr;
static cublasLtMatmulDesc_t op; static cublasLtMatrixLayout_t la,lb,lc,ld; static cublasLtMatmulPreference_t pref;
static cublasLtMatmulHeuristicResult_t heur[64]; static int nheur=0; static int curM=-1;
extern "C" size_t ver(){return cublasLtGetVersion();}
extern "C" int setup(int M,int N,int K,size_t ws,int req){
  if(!h) cublasLtCreate(&h);
  if(curM>=0){cublasLtMatmulPreferenceDestroy(pref);cublasLtMatrixLayoutDestroy(la);cublasLtMatrixLayoutDestroy(lb);cublasLtMatrixLayoutDestroy(lc);cublasLtMatrixLayoutDestroy(ld);cublasLtMatmulDescDestroy(op);}
  curM=M;
  cublasLtMatmulDescCreate(&op, CUBLAS_COMPUTE_32F, CUDA_R_32F);
  cublasOperation_t tA=CUBLAS_OP_T,tB=CUBLAS_OP_N;
  cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSA,&tA,sizeof(tA));
  cublasLtMatmulDescSetAttribute(op,CUBLASLT_MATMUL_DESC_TRANSB,&tB,sizeof(tB));
  cublasLtMatrixLayoutCreate(&la,CUDA_R_16BF,K,N,K); cublasLtMatrixLayoutCreate(&lb,CUDA_R_16BF,K,M,K);
  cublasLtMatrixLayoutCreate(&lc,CUDA_R_16BF,N,M,N); cublasLtMatrixLayoutCreate(&ld,CUDA_R_16BF,N,M,N);
  cublasLtMatmulPreferenceCreate(&pref);
  cublasLtMatmulPreferenceSetAttribute(pref,CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,&ws,sizeof(ws));
  nheur=0; int s=cublasLtMatmulAlgoGetHeuristic(h,op,la,lb,lc,ld,pref,req,heur,&nheur);
  return s? -s : nheur;
}
extern "C" int info(int i, int* o, float* w){
  cublasLtMatmulAlgo_t* a=&heur[i].algo; size_t wr; memset(o,0,sizeof(int)*10);
  int32_t id; uint32_t u; uint16_t s16;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_ID,&id,4,&wr); o[0]=id;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_TILE_ID,&u,4,&wr); o[1]=u;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_STAGES_ID,&u,4,&wr); o[2]=u;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_SPLITK_NUM,&u,4,&wr); o[3]=u;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME,&u,4,&wr); o[4]=u;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_CTA_SWIZZLING,&u,4,&wr); o[5]=u;
  s16=0; cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_CLUSTER_SHAPE_ID,&s16,2,&wr); o[6]=s16;
  int32_t sk=0; cublasLtMatmulAlgoCapGetAttribute(a,CUBLASLT_ALGO_CAP_SPLITK_SUPPORT,&sk,4,&wr); o[7]=sk;
  cublasLtMatmulAlgoConfigGetAttribute(a,CUBLASLT_ALGO_CONFIG_CUSTOM_OPTION,&u,4,&wr); o[8]=u;
  o[9]=(int)(heur[i].workspaceSize>>10); *w=heur[i].wavesCount; return heur[i].state;
}
// mode 0: C=R beta1 ; 1: C=D beta1 ; 2: beta0
extern "C" int run(int i,int mode,int splitk,const void*A,const void*R,const void*W,void*D,void*ws,size_t wsb,void*stream){
  cublasLtMatmulAlgo_t a=heur[i].algo;
  if(splitk>0){uint32_t s=splitk; cublasLtMatmulAlgoConfigSetAttribute(&a,CUBLASLT_ALGO_CONFIG_SPLITK_NUM,&s,4);
    uint32_t r=CUBLASLT_REDUCTION_SCHEME_COMPUTE_TYPE; cublasLtMatmulAlgoConfigSetAttribute(&a,CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME,&r,4);
    cublasLtMatmulHeuristicResult_t hr; int s2=cublasLtMatmulAlgoCheck(h,op,la,lb,lc,ld,&a,&hr); if(s2) return 1000+s2; }
  float al=1.f, be= mode==2?0.f:1.f; const void* C = mode==1? D : R;
