x=torch.randn(64,64,device='cuda',dtype=torch.bfloat16); y=x@x
L=ctypes.CDLL(d+'/lt.so'); L.ver.restype=ctypes.c_size_t; print('ver',L.ver())
print([l.split()[-1] for l in open('/proc/self/maps') if 'cublas' in l and 'r-xp' in l])
N=K=2560; WS=32<<20
ws=torch.empty(WS,dtype=torch.uint8,device='cuda')
W=torch.randn(N,K,device='cuda',dtype=torch.bfloat16)
from torch.profiler import profile, ProfilerActivity
def knames(fn):
    with profile(activities=[ProfilerActivity.CUDA]) as p: fn(); torch.cuda.synchronize()
    return [e.name[:90] for e in p.events() if e.device_type==torch.autograd.DeviceType.CUDA]
for M in [2048,4096,8192]:
    A=torch.randn(M,K,device='cuda',dtype=torch.bfloat16); R=torch.randn(M,N,device='cuda',dtype=torch.bfloat16); D=torch.empty(M,N,device='cuda',dtype=torch.bfloat16)
    n=L.setup(M,N,K,ctypes.c_size_t(WS),32); print('M',M,'nheur',n)
    o=(ctypes.c_int*10)(); w=ctypes.c_float()
    for i in range(n):
        L.info(i,o,ctypes.byref(w)); print(' ',i,list(o),round(w.value,2))
    s=torch.cuda.current_stream().cuda_stream
    def lt(i,mode,sk=0):
        return lambda A,R,W,D: L.run(i,mode,sk,ctypes.c_void_p(A.data_ptr()),ctypes.c_void_p(R.data_ptr()),ctypes.c_void_p(W.data_ptr()),ctypes.c_void_p(D.data_ptr()),ctypes.c_void_p(ws.data_ptr()),ctypes.c_size_t(WS),ctypes.c_void_p(torch.cuda.current_stream().cuda_stream))
    ref=(A.float()@W.float().t()+R.float())
    lt(0,0)(A,R,W,D); torch.cuda.synchronize(); print(' err0',(D.float()-ref).abs().max().item())
    print(' matmul:',knames(lambda: torch.matmul(A,W.t())))
    print(' lt0  :',knames(lambda: lt(0,0)(A,R,W,D)))
    print(' lt b0:',knames(lambda: lt(0,2)(A,R,W,D)))
    fns={'matmul':lambda A,R,W,D: torch.matmul(A,W.t(),out=D),'lt0':lt(0,0),'ltCeqD':lt(0,1),'ltb0':lt(0,2)}
    res={k:[] for k in fns}
    for rnd in range(3):
        for k,f in fns.items(): res[k].append(b200probe.harness_time(f,(A,R,W),(D,),warmup=5,rep=20,tries=1))
    print(' ',{k:[round(v,1) for v in vs] for k,vs in res.items()})

